1	// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
2	// file carries a version; files written by older versions of Tally are migrated when they are loaded.
3	package snapshot
4	
5	import (
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"time"
11	
12		"example.com/tally/internal/money"
13		"example.com/tally/internal/store"
14	)
15	
16	// Version is the version Save writes.
17	const Version = 2
18	
19	// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
20	var ErrUnsupportedVersion = errors.New("unsupported snapshot version")
21	
22	type fileV2 struct {
23		Version int         `json:"version"`
24		SavedAt time.Time   `json:"saved_at"`
25		State   store.State `json:"state"`
26	}
27	
28	// Save writes everything in st to path.
29	func Save(st *store.Store, path string, now time.Time) error {
30		b, err := json.MarshalIndent(fileV2{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
31		if err != nil {
32			return err
33		}
34		return os.WriteFile(path, append(b, '\n'), 0o600)
35	}
36	
37	// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
38	func Load(path string) (*store.Store, error) {
39		b, err := os.ReadFile(path)
40		if err != nil {
41			return nil, err
42		}
43		var head struct {
44			Version int `json:"version"`
45		}
46		if err := json.Unmarshal(b, &head); err != nil {
47			return nil, fmt.Errorf("snapshot %s: %w", path, err)
48		}
49		var st store.State
50		switch head.Version {
51		case 1:
52			if st, err = migrateV1(b); err != nil {
53				return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
54			}
55		case 2:
56			var f fileV2
57			if err := json.Unmarshal(b, &f); err != nil {
58				return nil, fmt.Errorf("snapshot %s: %w", path, err)
59			}
60			st = f.State
61		default:
62			return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
63		}
64		return store.FromState(st)
65	}
66	
67	// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
68	// full_name, and plans had a price in US cents (price_cents) and were all licensed.
69	type fileV1 struct {
70		Seq           int                  `json:"seq"`
71		Orgs          []orgV1              `json:"orgs"`
72		Users         []store.User         `json:"users"`
73		Members       []store.Member       `json:"members"`
74		APIKeys       []store.APIKey       `json:"api_keys"`
75		Customers     []customerV1         `json:"customers"`
76		Plans         []planV1             `json:"plans"`
77		Subscriptions []store.Subscription `json:"subscriptions"`
78		Invoices      []store.Invoice      `json:"invoices"`
79		Payments      []store.Payment      `json:"payments"`
80	}
81	
82	type orgV1 struct {
83		ID        string    `json:"id"`
84		Name      string    `json:"name"`
85		TaxRateBP int       `json:"tax_rate_bp"`
86		CreatedAt time.Time `json:"created_at"`
87	}
88	
89	type customerV1 struct {
90		ID        string    `json:"id"`
91		OrgID     string    `json:"org_id"`
92		FullName  string    `json:"full_name"`
93		Email     string    `json:"email"`
94		CreatedAt time.Time `json:"created_at"`
95	}
96	
97	type planV1 struct {
98		ID         string         `json:"id"`
99		OrgID      string         `json:"org_id"`
100		Name       string         `json:"name"`
101		PriceCents int64          `json:"price_cents"`
102		Interval   store.Interval `json:"interval"`
103		TrialDays  int            `json:"trial_days"`
104		CreatedAt  time.Time      `json:"created_at"`
105	}
106	
107	func migrateV1(b []byte) (store.State, error) {
108		var f fileV1
109		if err := json.Unmarshal(b, &f); err != nil {
110			return store.State{}, err
111		}
112		st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
113		for _, o := range f.Orgs {
114			st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
115		}
116		for _, c := range f.Customers {
117			st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
118		}
119		for _, p := range f.Plans {
120			st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
121				UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
122		}
123		return st, nil
124	}
