// formatInvoiceNumber returns the invoice number for sequence n, for example "INV-000042".
func formatInvoiceNumber(n int) string { return fmt.Sprintf("INV-%06d", n) }

// NumberInvoices gives every invoice without a number one, per organization, in creation order (created_at, then ID),
// and sets each organization's next number past its highest. Snapshots from before invoice numbers need it.
func (st *State) NumberInvoices() {
	sort.SliceStable(st.Invoices, func(i, j int) bool {
		a, b := st.Invoices[i], st.Invoices[j]
		if !a.CreatedAt.Equal(b.CreatedAt) {
			return a.CreatedAt.Before(b.CreatedAt)
		}
		return a.ID < b.ID
	})
	if st.InvoiceNext == nil {
		st.InvoiceNext = map[string]int{}
	}
	for i := range st.Invoices {
		inv := &st.Invoices[i]
		if inv.Number != "" {
			continue
		}
		st.InvoiceNext[inv.OrgID]++
		inv.Number = formatInvoiceNumber(st.InvoiceNext[inv.OrgID])
	}
}

