import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Version 2 (Tally 0.y) had no invoice numbers.
type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. It writes a temporary file beside path and renames it over path, so path always
// holds either the previous snapshot or the whole new one.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAtomic(path, append(b, '\n'))
}

func writeFileAtomic(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	return os.Rename(f.Name(), path)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return decode(path, b)
}

// decode returns the store in the snapshot b, the contents of path.
func decode(path string, b []byte) (*store.Store, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		var err error
		if st, err = migrateV1(b); err != nil {
			return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		st.NumberInvoices()
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
		st.NumberInvoices()
	case 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Upgrade rewrites the snapshot at path as the current version. The file is first copied byte for byte to
// "<path>.v<old version>.bak". A snapshot already at the current version is left alone, without a backup. A snapshot of a
// newer version fails with ErrUnsupportedVersion and is left alone.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if head.Version == Version {
		return nil
	}
	// Decoding first refuses unreadable files before a backup is made.
	st, err := decode(path, b)
	if err != nil {
		return err
	}
	if err := os.WriteFile(fmt.Sprintf("%s.v%d.bak", path, head.Version), b, 0o600); err != nil {
		return err
	}
	return Save(st, path, time.Now())
}

