package snapshot

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

func TestSaveAndLoad(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "Europe/Berlin", 1900, now)
	u, _ := st.CreateUser("ann@example.com", "Ann", now)
	_, _ = st.AddMember(o.ID, u.ID, store.RoleOwner, now)
	k, _ := st.CreateAPIKey(o.ID, u.ID, "k", now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	_, _ = st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 150}}}, now)

	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Export(), st.Export()) {
		t.Fatal("the loaded store differs from the saved one")
	}
	if _, ok := got.APIKeyByToken(k.Token); !ok {
		t.Fatal("API keys do not work after a reload")
	}
}

func TestSaveWritesVersion3Atomically(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	st := store.New()
	_, _ = st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	_, _ = st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	if v := versionOf(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("Save left files behind: %v", entries)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Export(), st.Export()) {
		t.Fatal("the second save did not replace the first")
	}
}

func TestLoadVersion1(t *testing.T) {
	st, err := Load(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	o, ok := st.Org("org_000001")
	if !ok || o.Plan != store.OrgFree || o.TimeZone != "UTC" || o.TaxRateBP != 825 {
		t.Fatalf("org = %+v", o)
	}
	c, ok := st.Customer(o.ID, "cus_000004")
	if !ok || c.Name != "Jane Doe" || c.Email != "jane@example.com" {
		t.Fatalf("customer = %+v", c)
	}
	p, ok := st.Plan(o.ID, "plan_000005")
	if !ok || p.Currency != money.USD || p.UnitAmount != 1999 || p.UsageType != store.Licensed || !p.Active {
		t.Fatalf("plan = %+v", p)
	}
	if k, ok := st.APIKeyByToken("tly_00000000000000000000000000000003"); !ok || k.UserID != "usr_000002" {
		t.Fatalf("key = %+v", k)
	}
	inv, ok := st.Invoice(o.ID, "in_000007")
	if !ok || inv.Lines[0].UnitAmount != 1999 || inv.Status != store.InvoicePaid || inv.Number != "INV-000001" {
		t.Fatalf("invoice = %+v", inv)
	}
	next, err := st.CreateCustomer(o.ID, "New", "new@example.com", time.Now())
	if err != nil || next.ID == "cus_000004" || next.ID <= "cus_000008" {
		t.Fatalf("the next ID %q reuses an old one: %v", next.ID, err)
	}
}

func TestLoadVersion2NumbersInvoices(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	a, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	b, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	ca, _ := st.CreateCustomer(a.ID, "Jane", "jane@example.com", now)
	cb, _ := st.CreateCustomer(b.ID, "John", "john@example.com", now)
	line := []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	// The first invoice created has the latest created_at, so creation order is not ID order.
	late, _ := st.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: line}, now.Add(time.Hour))
	early, _ := st.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: line}, now)
	other, _ := st.CreateInvoice(store.Invoice{OrgID: b.ID, CustomerID: cb.ID, Currency: money.USD, Lines: line}, now)

	// A version 2 file has no numbers and no next numbers.
	state := st.Export()
	for i := range state.Invoices {
		state.Invoices[i].Number = ""
	}
	state.InvoiceNext = nil
	path := filepath.Join(t.TempDir(), "tally.json")
	writeFile(t, path, fileV2{Version: 2, SavedAt: now, State: state})

	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range []struct{ org, id, number string }{{a.ID, early.ID, "INV-000001"}, {a.ID, late.ID, "INV-000002"}, {b.ID, other.ID, "INV-000001"}} {
		if inv, ok := got.Invoice(c.org, c.id); !ok || inv.Number != c.number {
			t.Fatalf("invoice %s has number %q, want %q", c.id, inv.Number, c.number)
		}
	}
	next, err := got.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.USD, Lines: line}, now)
	if err != nil || next.Number != "INV-000003" {
		t.Fatalf("the next invoice has number %q: %v", next.Number, err)
	}
}

func TestUpgradeVersion1(t *testing.T) {
	orig, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak, err := os.ReadFile(path + ".v1.bak"); err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup is not the original file: %v", err)
	}
	if v := versionOf(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	st, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if inv, ok := st.Invoice("org_000001", "in_000007"); !ok || inv.Number != "INV-000001" {
		t.Fatalf("invoice = %+v", inv)
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 2 {
		t.Fatalf("Upgrade left files behind: %v", entries)
	}

	// A version 3 file is left alone, without a backup.
	upgraded, _ := os.ReadFile(path)
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if again, _ := os.ReadFile(path); !bytes.Equal(again, upgraded) {
		t.Fatal("upgrading a version 3 file changed it")
	}
	if _, err := os.Stat(path + ".v3.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a version 3 file got a backup: %v", err)
	}
}

func TestUpgradeRefusesUnknownVersions(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "future.json")
	orig := []byte(`{"version": 9, "state": {}}`)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, orig) {
		t.Fatal("a file of an unsupported version was changed")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("Upgrade left files behind: %v", entries)
	}
}

func TestLoadRefusesUnknownVersions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "future.json")
	if err := os.WriteFile(path, []byte(`{"version": 9, "state": {}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if _, err := Load(filepath.Join(t.TempDir(), "missing.json")); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("missing file: %v", err)
	}
